def _digits(value):
    if not isinstance(value, str):
        return ""
    digits = value.replace(" ", "").replace("-", "")
    return digits if digits.isascii() and digits.isdigit() else ""


def _checksum(digits):
    total = 0
    for position, char in enumerate(reversed(digits)):
        digit = int(char)
        if position % 2:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10


def is_valid(number):
    digits = _digits(number)
    return len(digits) >= 2 and _checksum(digits) == 0


def check_digit(partial):
    digits = _digits(partial)
    if not digits:
        raise ValueError("expected one or more ASCII digits with optional spaces and hyphens")
    return str(-_checksum(digits + "0") % 10)
